let lang = 'hy';
try { const s = localStorage.getItem('lang'); if (s === 'en' || s === 'hy') lang = s; } catch { /* storage unavailable */ }

export const getLang = () => lang;
export function setLang(l) {
  lang = l === 'en' ? 'en' : 'hy';
  try { localStorage.setItem('lang', lang); } catch { /* ignore */ }
  document.documentElement.lang = lang;
}

export function t(key, params) {
  let s = DICT[lang][key] ?? DICT.en[key];
  if (s === undefined) { console.warn('[i18n] missing key', key); return key; }
  if (params) s = s.replace(/\{(\w+)\}/g, (m, k) => (params[k] ?? m));
  return s;
}
t.has = (key) => key in DICT[lang] || key in DICT.en;
export const dictionaries = DICT;
